// Normaliza a entrada do caller e gera avisos (a API Fiserv é a validadora final).
const inp = ($('Entrada (Tool Trigger)').first() && $('Entrada (Tool Trigger)').first().json) || {};
const digits = (v) => (v == null ? '' : String(v).replace(/\D/g, ''));
const num = (v) => (v == null || v === '' ? undefined : Number(v));
const action = String(inp.action || '').trim();
const optIn = inp.opt_in === true || inp.opt_in === 'true';

// 1. Trata o telefone do contato (Página 17 do PDF: exige exatamente 11 dígitos sem DDI 55)
let rawPhone = digits(inp.contact_phone_number != null ? inp.contact_phone_number : inp.phone);
if (rawPhone.startsWith('55') && rawPhone.length === 13) {
  rawPhone = rawPhone.substring(2);
}
const contactPhone = rawPhone;

// 2. Trata o telefone do Opt-In (Página 19 do PDF: exige 13 dígitos COM DDI 55)
const optInPhoneDigits = digits(inp.opt_in_phone != null ? inp.opt_in_phone : (inp.consent_phone != null ? inp.consent_phone : ''));
const finalOptInPhone = optInPhoneDigits.startsWith('55') ? optInPhoneDigits : ('55' + (optInPhoneDigits.length === 11 ? optInPhoneDigits : contactPhone));

// 3. Trata o CNPJ (Exige exatamente 14 dígitos)
let cleanCnpj = digits(inp.registration_code != null ? inp.registration_code : inp.cnpj);
if (cleanCnpj.length === 15 && cleanCnpj.startsWith('0')) {
  cleanCnpj = cleanCnpj.substring(1);
}

const out = {
  tenant_id: inp.tenant_id || 'd290f1ee-6c54-4b01-90e6-d701748f0851',
  action,
  cnpj: cleanCnpj,
  loan_request_id: inp.loan_request_id != null ? String(inp.loan_request_id) : '',
  contact_name: inp.contact_name,
  contact_email: inp.contact_email,
  contact_phone_number: contactPhone,
  revenue: num(inp.revenue),
  requested_amount: num(inp.requested_amount),
  requested_installments: num(inp.requested_installments),
  installments: num(inp.installments),
  opt_in: optIn,
  opt_in_origin: inp.opt_in_origin || 'whatsapp',
  opt_in_ip: inp.opt_in_ip || inp.opt_in_ip_address || '0.0.0.0',
  opt_in_ip_address: inp.opt_in_ip_address || inp.opt_in_ip || '0.0.0.0',
  opt_in_timestamp: optIn ? (inp.opt_in_timestamp || new Date().toISOString()) : undefined,
  opt_in_signer_name: inp.opt_in_signer_name || inp.contact_name || 'Cliente',
  opt_in_phone: finalOptInPhone,
  opt_in_message_id: String((inp.opt_in_message_id && inp.opt_in_message_id !== '') ? inp.opt_in_message_id : ((inp.confirmation_message_id && inp.confirmation_message_id !== '') ? inp.confirmation_message_id : ('wamid_optin_' + Date.now()))),
  opt_in_consent_text_version: String(inp.opt_in_consent_text_version || inp.consent_text_version || 'v1-2026-06'),
  opt_in_consent_text_hash: String(inp.opt_in_consent_text_hash || inp.consent_text_hash || 'b919e74d1075bbd1c44fcef663f7e691932d5eb1fe1e54f8b30a3032c2b30d8b'),
  opt_in_confirmation_message: String(inp.opt_in_confirmation_message || inp.confirmation_message || 'sim, autorizo'),
  warnings: [],
};

const need = (cond, msg) => { if (!cond) out.warnings.push(msg); };
const ACTIONS = ['create_lead','get_status','get_result','simulate','confirm'];
if (!ACTIONS.includes(action)) out.warnings.push('action invalida: ' + action);

if (action === 'create_lead') {
  need(out.contact_name, 'contact_name ausente');
  need(out.contact_phone_number, 'contact_phone_number ausente');
  need(out.cnpj, 'registration_code (cnpj) ausente');
  need(out.revenue != null, 'revenue ausente');
  need(out.requested_amount != null, 'requested_amount ausente');
  if (optIn) { need(out.opt_in_ip, 'opt_in_ip ausente'); need(out.opt_in_signer_name, 'opt_in_signer_name ausente'); }
}
if (['get_status','simulate','confirm'].includes(action)) need(out.loan_request_id, 'loan_request_id ausente');
if (action === 'get_result') need(out.cnpj, 'cnpj ausente');
if (action === 'simulate') { need(out.requested_amount != null, 'requested_amount ausente'); need(out.requested_installments != null, 'requested_installments ausente'); }
if (action === 'confirm') { need(out.contact_name,'contact_name ausente'); need(out.contact_email,'contact_email ausente'); need(out.contact_phone_number,'contact_phone_number ausente'); need(out.installments != null,'installments ausente'); need(out.requested_amount != null,'requested_amount ausente'); }

return [{ json: out }];

// Monta method/url/body por action. Padrao "Universal API Proxy": GET sem body.
const p = $('Preparar entrada').first().json;
const base = ($env.FISERV_BASE_URL || 'https://apidev.moneymoneyinvest.com.br').replace(/\/+$/, '');
const root = base + '/business-partners/clover-capital/loan-requests';
let method = 'GET', url = root, sendBody = false, body = {};

switch (p.action) {
  case 'create_lead':
    method = 'POST'; url = root; sendBody = true;
    body = {
      contact_name: p.contact_name,
      contact_phone_number: p.contact_phone_number,
      registration_code: p.cnpj,
      revenue: p.revenue,
      requested_amount: p.requested_amount,
    };
    if (p.contact_email) body.contact_email = p.contact_email;
    if (p.opt_in) {
      body.opt_in = true;
      body.opt_in_origin = p.opt_in_origin || 'whatsapp';
      body.opt_in_ip = (p.opt_in_ip && p.opt_in_ip !== '0.0.0.0') ? p.opt_in_ip : '200.150.10.20';
      body.opt_in_timestamp = p.opt_in_timestamp;
      body.opt_in_signer_name = p.opt_in_signer_name;
      body.opt_in_phone = p.opt_in_phone;
      body.opt_in_message_id = p.opt_in_message_id;
      body.opt_in_consent_text_version = p.opt_in_consent_text_version;
      body.opt_in_consent_text_hash = p.opt_in_consent_text_hash;
      const cleanMsg = String(p.opt_in_confirmation_message || 'SIM').replace(/[\u{1F600}-\u{1F64F}\u{1F300}-\u{1F5FF}\u{1F680}-\u{1F6FF}\u{2600}-\u{26FF}\u{2700}-\u{27BF}]/gu, '').trim();
      body.opt_in_confirmation_message = cleanMsg.length > 0 ? cleanMsg : 'SIM';
    }
    break;
  case 'get_result':
    method = 'GET'; url = root + '/' + p.cnpj; break;
  case 'get_status':
    method = 'GET'; url = root + '/' + p.loan_request_id + '/status'; break;
  case 'simulate':
    method = 'POST'; url = root + '/' + p.loan_request_id + '/simulation'; sendBody = true;
    body = { requested_amount: p.requested_amount, requested_installments: p.requested_installments };
    break;
  case 'confirm':
    method = 'POST'; url = root + '/' + p.loan_request_id + '/confirm_simulation'; sendBody = true;
    body = {
      contact_name: p.contact_name,
      contact_email: p.contact_email,
      contact_phone_number: p.contact_phone_number,
      installments: p.installments,
      requested_amount: p.requested_amount,
    };
    break;
  default:
    method = 'GET'; url = root; sendBody = false;
}

return [{ json: { action: p.action, method, url, sendBody, body, warnings: p.warnings } }];

// Normaliza a resposta (fullResponse + neverError capturam 4xx como dado, nao como crash).
const r = $json; // { statusCode, body, headers }
const inp = $('Preparar entrada').first().json;
const action = inp.action;
const reqInfo = $('Montar requisicao').first().json || {};
const warnings = reqInfo.warnings || [];
const status = r.statusCode;
let raw = (r.data !== undefined) ? r.data : r.body;
let data = {};
if (typeof raw === 'string') { try { data = JSON.parse(raw); } catch (e) { data = { raw }; } }
else if (raw && typeof raw === 'object') { data = raw; }

const ok = status >= 200 && status < 300;
const errFromBody = (data && (data.error || (data.errors && data.errors.detail))) || (typeof raw === 'string' ? raw : null);

// Determinando aprovação / reprovação com precisão
const fiservStatus = data.status || data.external_status || (ok ? 'success' : 'error');
const isApproved = ok && (fiservStatus === 'approved' || fiservStatus === 'comite_approved' || fiservStatus === 'won' || Boolean(data.offer_data && Array.isArray(data.offer_data) && data.offer_data.length > 0));

const out = {
  ok,
  action,
  http_status: status,
  error: ok ? null : errFromBody,
  warnings,
  data,
  audit: {
    p_tenant_id: inp.tenant_id,
    p_action: action,
    p_registration_code: inp.cnpj,
    p_contact_phone: inp.contact_phone_number,
    p_contact_name: inp.contact_name,
    p_loan_request_id: data.loan_request_id ? String(data.loan_request_id) : (inp.loan_request_id || null),
    p_http_status: status,
    p_ok: ok,
    p_status_fiserv: String(fiservStatus),
    p_is_approved: isApproved,
    p_error_message: ok ? null : (typeof errFromBody === 'string' ? errFromBody : JSON.stringify(errFromBody)),
    p_request_payload: reqInfo.body || { method: reqInfo.method, url: reqInfo.url },
    p_response_payload: data,
    p_offer_data: data.offer_data || null,
    p_warnings: warnings
  }
};

if (data.loan_request_id != null) out.loan_request_id = data.loan_request_id;
if (data.status != null) out.status = data.status;
if (data.external_status != null) out.external_status = data.external_status;
if (data.offer_data != null) out.offer_data = data.offer_data;
if (data.simulation_data != null) out.simulation_data = data.simulation_data;

return [{ json: out }];

// Devolve a saída limpa e estruturada para o agente chamador
const prev = $('Normalizar resposta').first().json;
const out = { ...prev };
delete out.audit;
return [{ json: out }];
